package com.medcore.backend.api.internaciones;
import com.medcore.backend.api.infraestructura.camas.Cama;
import com.medcore.backend.api.infraestructura.camas.CamaRepository;
import com.medcore.backend.api.infraestructura.camas.EstadoCama;
import com.medcore.backend.api.pacientes.*;import com.medcore.backend.api.profesionales.*;
import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;
@Service public class InternacionService{
 private final InternacionRepository repository;private final PacienteRepository pacientes;private final ProfesionalRepository profesionales;private final CamaRepository camas;
 public InternacionService(InternacionRepository repository,PacienteRepository pacientes,ProfesionalRepository profesionales,CamaRepository camas){this.repository=repository;this.pacientes=pacientes;this.profesionales=profesionales;this.camas=camas;}
 @Transactional public InternacionResponse crear(InternacionRequest r){Paciente p=pacientes.findById(r.pacienteId()).orElseThrow(() -> new InternacionExceptions.InternacionInvalidaException("Paciente no encontrado: "+r.pacienteId()));if(p.getEstado()!=EstadoPaciente.ACTIVO)throw new InternacionExceptions.InternacionInvalidaException("El paciente se encuentra inactivo");if(!repository.findByPacienteIdAndEstado(r.pacienteId(),EstadoInternacion.ACTIVA).isEmpty())throw new InternacionExceptions.InternacionInvalidaException("El paciente ya tiene una internación activa");Profesional prof=profesionales.findById(r.profesionalId()).orElseThrow(() -> new InternacionExceptions.InternacionInvalidaException("Profesional no encontrado: "+r.profesionalId()));if(prof.getEstado()!=EstadoProfesional.ACTIVO)throw new InternacionExceptions.InternacionInvalidaException("El profesional se encuentra inactivo");Cama cama=camas.findByIdForUpdate(r.camaId()).orElseThrow(() -> new InternacionExceptions.InternacionInvalidaException("Cama no encontrada: "+r.camaId()));if(cama.getEstado()!=EstadoCama.DISPONIBLE)throw new InternacionExceptions.InternacionInvalidaException("La cama no está disponible");cama.setEstado(EstadoCama.OCUPADA);camas.save(cama);Internacion i=new Internacion();i.setPacienteId(r.pacienteId());i.setProfesionalId(r.profesionalId());i.setMotivoInternacion(r.motivoInternacion().trim());i.setDiagnosticoIngreso(r.diagnosticoIngreso());i.setCamaId(r.camaId());i.setAdmisionId(r.admisionId());return InternacionResponse.from(repository.save(i));}
 @Transactional(readOnly=true) public Page<InternacionResponse> listar(Pageable p){return repository.findAll(p).map(InternacionResponse::from);}@Transactional(readOnly=true)public InternacionResponse obtener(Long id){return InternacionResponse.from(buscar(id));}
 @Transactional public InternacionResponse alta(Long id){Internacion i=buscar(id);if(i.getEstado()!=EstadoInternacion.ACTIVA)throw new InternacionExceptions.InternacionInvalidaException("Solo una internación activa puede recibir el alta");i.setEstado(EstadoInternacion.ALTA_MEDICA);i.setFechaAlta(LocalDateTime.now(ZoneId.of("America/Argentina/Buenos_Aires")));Cama cama=camas.findByIdForUpdate(i.getCamaId()).orElseThrow(() -> new InternacionExceptions.InternacionInvalidaException("Cama no encontrada"));cama.setEstado(EstadoCama.DISPONIBLE);camas.save(cama);return InternacionResponse.from(repository.save(i));}
 private Internacion buscar(Long id){return repository.findById(id).orElseThrow(() -> new InternacionExceptions.InternacionNoEncontradaException(id));}
}
